package com.hoyoung.assistant.runtime;
import android.app.Application;import android.content.Context;import androidx.test.core.app.ApplicationProvider;import com.hoyoung.assistant.store.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import org.robolectric.annotation.SQLiteMode;import java.io.File;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class ActionReceiptPrivacyTest{
 private Context context;private HoyoungStore store;private ActionReceiptJournal journal;
 @Before public void before()throws Exception{context=ApplicationProvider.getApplicationContext();context.deleteDatabase(HoyoungStore.DATABASE_NAME);delete(context.getFilesDir());context.getFilesDir().mkdirs();store=new HoyoungStore(context);journal=new ActionReceiptJournal(store);journal.ensureIndex();}
 @After public void after()throws Exception{store.close();context.deleteDatabase(HoyoungStore.DATABASE_NAME);delete(context.getFilesDir());}
 private long owner(String root,String text)throws Exception{long id=store.addMessage("user",text,root).getLong("id");store.putSetting("requestSource:"+root,""+id);return id;}
 private void exclude(long id)throws Exception{store.getPrivacyLedger().excludeSource("message",id,store.getMessage(id).getString("content_hash"),"retrieval_exclude","owner exclusion");}
 @Test public void exclusionBeforeReconciliationMasksArchivedReferencedOriginalWhileUnrelatedRootSurvives()throws Exception{long old=owner("old","PRIVATE-RECEIPT-7134");owner("root","allowed question");owner("clean","allowed clean question");JSONObject original=store.readOriginalText(old,0,1000);journal.put("actionReceipt:root:read",new JSONObject().put("status","uncertain").put("name","memory.source.read").put("result",new JSONObject().put("original",original)));journal.put("actionReceipt:clean:read",new JSONObject().put("status","uncertain").put("name","files.read").put("result",new JSONObject().put("text","CLEAN-RECEIPT-AVAILABLE")));exclude(old);journal.resolveFor("root",true);journal.resolveFor("clean",true);long archived=journal.get("actionReceipt:root:read").getLong("previousReceiptSourceMessageId");assertFalse(store.getSetting("answerSources:"+archived,"").isEmpty());MemoryGateway.Prepared p=new MemoryGateway(store).prepare("receipt-dispatch","receipt-root","user",0,"hello",null,80000);assertFalse(p.context.contains("PRIVATE-RECEIPT-7134"));assertTrue(p.context.contains("CLEAN-RECEIPT-AVAILABLE"));}
 @Test public void exclusionAfterArchiveMasksTransitivePreviousReceiptCopyAndAtomicFailureRollsBack()throws Exception{long old=owner("root","PRIVATE-RECEIPT-5218");journal.put("actionReceipt:root:first",new JSONObject().put("status","uncertain").put("name","files.read").put("result",new JSONObject().put("text","PRIVATE-RECEIPT-5218")));journal.resolveFor("root",true);long first=journal.get("actionReceipt:root:first").getLong("previousReceiptSourceMessageId");journal.put("actionReceipt:root:second",new JSONObject().put("status","uncertain").put("previousReceiptSourceMessageId",first).put("result",new JSONObject().put("text","PRIVATE-RECEIPT-5218")));journal.resolveFor("root",true);exclude(old);MemoryGateway.Prepared p=new MemoryGateway(store).prepare("receipt-dispatch","receipt-root","user",0,"hello",null,80000);assertFalse(p.context.contains("PRIVATE-RECEIPT-5218"));owner("failure","clean failure root");journal.put("actionReceipt:failure:read",new JSONObject().put("status","uncertain"));long count=store.messageCount();store.getWritableDatabase().execSQL("CREATE TRIGGER reject_receipt_binding BEFORE INSERT ON settings WHEN NEW.setting_key LIKE 'answerSources:%' BEGIN SELECT RAISE(ABORT,'fixture binding failure'); END");assertThrows(RuntimeException.class,()->journal.resolveFor("failure",true));assertEquals(count,store.messageCount());assertEquals("uncertain",journal.get("actionReceipt:failure:read").getString("status"));}
 private static void delete(File f)throws Exception{if(!f.exists())return;if(f.isDirectory()){File[] children=f.listFiles();if(children==null)throw new java.io.IOException("Unreadable fixture");for(File c:children)delete(c);}if(!f.delete())throw new java.io.IOException("Fixture cleanup failed");}
}
